WITH RECURSIVE TagAncestorTags AS (
    SELECT
        t.Id,
        t.TagName,
        0 AS Depth
    FROM Tags t
    WHERE t.IsRequired = 1

    UNION ALL

    SELECT
        t2.Id,
        t2.TagName,
        ta.Depth + 1
    FROM Tags t2
    INNER JOIN Tags t_rel ON t2.Id = t_rel.Id
    JOIN TagsParent TP ON TP.ChildTagId = t2.Id
    JOIN TagAncestorTags ta ON ta.TagName = TP.ParentTagName 
    -- Slight meaningfulness provided assuming tag parent tree simulated;
